/* Laboratoire de cas : affaires, enquêtes et incidents réels du droit des Nations Unies. Faits paraphrasés à des fins pédagogiques. Lisez toujours le texte intégral avant de le citer. */
TRACK.cases = [
{id:'c-reparation', title:'L’ONU peut-elle présenter elle-même une réclamation ?', where:'CIJ · Avis consultatif', when:'Réparation des dommages, 11 avril 1949', tags:['Personnalité juridique','Protection fonctionnelle','Fondements'],
 teaser:'Un médiateur de l’ONU est assassiné à Jérusalem. La Charte ne dit nulle part que l’ONU a la personnalité juridique. Qui peut réclamer ?',
 facts:`<p>Le comte Folke Bernadotte, Médiateur de l’ONU en Palestine, est assassiné à Jérusalem le 17 septembre 1948. L’Assemblée générale demande à la Cour si l’ONU peut présenter une réclamation internationale pour le dommage causé à elle-même et à son agent. La Cour conclut que l’ONU possède la personnalité juridique internationale, indispensable à ses buts et fonctions, et que celle-ci est opposable même aux non-membres. Elle peut réclamer pour son propre dommage et, au titre de la protection fonctionnelle, pour celui de son agent.</p>`,
 decide:{q:'Vous conseillez le Secrétaire général en 1948. Que dites-vous ?',o:[
  {t:'L’ONU ne peut pas réclamer : seuls les États sont sujets du droit international, et seul l’État national de Bernadotte peut agir.',ok:false,why:'La Cour a jugé que les sujets de droit international ne sont pas nécessairement identiques par leur nature, et que l’ONU a des droits propres.'},
  {t:'L’ONU peut réclamer pour son propre dommage et pour son agent, car cette capacité découle implicitement de ses fonctions.',ok:true,why:'C’est le cœur de l’avis : pouvoirs implicites et protection fonctionnelle.'},
  {t:'L’ONU ne peut réclamer qu’à l’encontre des États Membres, car les non-membres n’ont jamais accepté sa personnalité.',ok:false,why:'La Cour a qualifié cette personnalité d’objective : elle peut donc être invoquée aussi contre un non-membre.'}]},
 questions:['Où la Cour trouve-t-elle la personnalité dans la Charte, si aucun article ne la mentionne ?','Quelle différence entre personnalité et qualité d’État ?','Que se passe-t-il si la réclamation de l’ONU concurrence celle de l’État de la victime ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>L’ONU a-t-elle qualité pour présenter une réclamation internationale pour le préjudice causé à elle-même et à ses agents ?</div><div><b class="k">Rule</b>Buts et fonctions de la Charte (art. 1, 2, 104, 105) ; pouvoirs implicites.</div><div><b class="k">Application</b>L’ONU exerce sur le plan international des droits et des devoirs qui présupposent la personnalité, et ses agents ne peuvent travailler que s’ils peuvent compter sur sa protection.</div><div><b class="k">Conclusion</b>Oui pour les deux réclamations. La personnalité est objective, mais l’Organisation n’a que les droits que ses fonctions exigent.</div></div>`,
 trainer:'<p>Demandez aux militaires pourquoi cela les concerne : la protection fonctionnelle est la base juridique sur laquelle l’ONU soutient son personnel.</p>',
 sources:[{t:'CIJ : Réparation des dommages',u:'https://www.icj-cij.org/case/4'}]},

{id:'c-expenses', title:'Qui paie le maintien de la paix ?', where:'CIJ · Avis consultatif', when:'Certaines dépenses des Nations Unies, 20 juillet 1962', tags:['Budget','Ultra vires','Assemblée générale'],
 teaser:'Des Membres refusent de payer pour les opérations de Suez et du Congo, au motif que seul le Conseil de sécurité peut agir.',
 facts:`<p>Plusieurs États Membres refusent de payer leurs contributions à la FUNU (Moyen-Orient) et à l’ONUC (Congo). L’Assemblée demande si ces coûts sont des « dépenses de l’Organisation » au sens de l’Article 17, paragraphe 2. Par neuf voix contre cinq, la Cour répond oui. Une action appropriée à la réalisation d’un but déclaré de l’ONU est présumée ne pas être ultra vires. La responsabilité du Conseil en matière de paix est principale, non exclusive, et ces opérations n’étaient pas des actions coercitives qui lui seraient réservées.</p>`,
 decide:{q:'Une délégation refuse de payer et qualifie l’opération d’illégale. Quelle est la meilleure réponse ?',o:[
  {t:'Si une action sert un but déclaré de l’ONU, elle est présumée licite et ses coûts relèvent de l’Article 17, paragraphe 2.',ok:true,why:'C’est la présomption appliquée par la Cour.'},
  {t:'Un État peut licitement retenir ses contributions dès lors qu’il estime une opération illégale.',ok:false,why:'La Cour a écarté ce résultat : les dépenses s’imposaient aux Membres.'},
  {t:'Seules les opérations du Chapitre VII peuvent être imputées au budget de l’ONU.',ok:false,why:'La FUNU et l’ONUC n’étaient pas des actions coercitives, et leurs coûts étaient pourtant des dépenses de l’Organisation.'}]},
 questions:['Que dit l’avis sur l’organe qui décide si un acte est ultra vires ?','Quel lien avec la crise de liquidités actuelle ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Les coûts de la FUNU et de l’ONUC sont-ils des dépenses au sens de l’Article 17, paragraphe 2 ?</div><div><b class="k">Rule</b>Art. 11, 14, 17, 24 ; présomption de validité des actions servant les buts de l’ONU.</div><div><b class="k">Application</b>Les deux opérations servaient le maintien de la paix, et aucune n’était une action coercitive contre un État.</div><div><b class="k">Conclusion</b>Il s’agissait de dépenses de l’Organisation, à supporter par les Membres selon la répartition fixée.</div></div>`,
 sources:[{t:'CIJ : Certaines dépenses',u:'https://www.icj-cij.org/case/49'}]},

{id:'c-namibia', title:'L’abstention vaut-elle veto ?', where:'CIJ · Avis consultatif', when:'Namibie, 21 juin 1971', tags:['Conseil de sécurité','Art. 25','Vote'],
 teaser:'L’Afrique du Sud reste en Namibie après la fin de son mandat et soutient que la résolution du Conseil est nulle parce que des membres permanents se sont abstenus.',
 facts:`<p>L’Assemblée générale met fin en 1966 au mandat de l’Afrique du Sud sur le Sud-Ouest africain (Namibie), et la résolution 276 (1970) du Conseil de sécurité déclare illégale sa présence continue. L’Afrique du Sud objecte notamment que les abstentions de membres permanents invalident la résolution. La Cour juge qu’une pratique longue et acceptée ne fait pas de l’abstention volontaire un obstacle à l’adoption, que la présence sud-africaine est illégale et que les décisions au titre de l’Article 25 lient les Membres.</p>`,
 decide:{q:'Un diplomate affirme que la résolution 276 est nulle à cause des abstentions. Vous répondez :',o:[
  {t:'Exact : l’Article 27, paragraphe 3, exige le vote affirmatif des cinq, donc l’abstention vaut veto.',ok:false,why:'La Cour s’est appuyée sur une pratique constante acceptée par les Membres pour écarter cette lecture.'},
  {t:'Seules les décisions du Chapitre VII lient au titre de l’Article 25 ; la résolution n’est donc de toute façon que consultative.',ok:false,why:'La Cour a dit que l’Article 25 ne se limite pas au Chapitre VII ; ce sont les termes et le contexte de la résolution qui décident.'},
  {t:'L’abstention n’empêche pas l’adoption, et la décision peut lier les Membres quel que soit le chapitre sur lequel elle repose.',ok:true,why:'Ces deux points sont tirés de l’avis.'}]},
 questions:['Comment la pratique peut-elle façonner le sens de l’Article 27, paragraphe 3 ?','Quelles obligations l’avis fait-il peser sur les États tiers ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Quelles sont les conséquences juridiques de la présence continue de l’Afrique du Sud, et la résolution était-elle valide ?</div><div><b class="k">Rule</b>Art. 24, 25, 27, par. 3 ; pratique du Conseil.</div><div><b class="k">Application</b>L’abstention était acceptée de longue date, et les termes de la résolution montraient l’intention de lier.</div><div><b class="k">Conclusion</b>La présence était illégale et devait cesser ; les Membres étaient tenus de reconnaître cette illégalité.</div></div>`,
 sources:[{t:'CIJ : Namibie',u:'https://www.icj-cij.org/case/53'}]},

{id:'c-nicaragua', title:'Force, agression armée et légitime défense', where:'CIJ · Contentieux', when:'Nicaragua c. États-Unis, fond, 27 juin 1986', tags:['Art. 2, par. 4','Art. 51','Attribution'],
 teaser:'Un État arme des rebelles et mine des ports, puis invoque la légitime défense collective. Où passe la limite ?',
 facts:`<p>Le Nicaragua attaque les États-Unis pour leur soutien aux contras, le minage de ports et des attaques contre des installations. Les États-Unis se sont retirés de la phase du fond. Appliquant le droit coutumier, la Cour juge qu’ils ont violé l’interdiction du recours à la force et celle de l’intervention. Seules les formes les plus graves d’emploi de la force constituent une agression armée ; armer des rebelles n’en est pas une, et la légitime défense collective suppose une demande de la victime. Les actes des contras eux-mêmes ne sont pas attribués aux États-Unis, faute de contrôle effectif établi.</p>`,
 decide:{q:'Un État fournit des armes à des rebelles chez son voisin. L’allié de ce voisin peut-il riposter par la force au titre de la légitime défense collective ?',o:[
  {t:'Oui : tout soutien à des rebelles est une agression armée.',ok:false,why:'Selon la Cour, la fourniture d’armes peut être un emploi illicite de la force ou une intervention, mais non une agression armée.'},
  {t:'Pas sur cette base : la seule fourniture d’armes n’est pas une agression armée, et la victime doit se déclarer attaquée et demander de l’aide.',ok:true,why:'Cela correspond au seuil de gravité et aux conditions de la légitime défense collective posés par la Cour.'},
  {t:'Oui, si le Conseil de sécurité n’a pas agi dans les 30 jours.',ok:false,why:'Cette règle n’existe pas ; l’Article 51 exige une agression armée et une information du Conseil.'}]},
 questions:['Pourquoi la Cour a-t-elle appliqué la coutume plutôt que la Charte ?','Comment le « contrôle effectif » revient-il dans les affaires d’attribution en maintien de la paix ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Les États-Unis pouvaient-ils justifier leurs actes par la légitime défense collective ?</div><div><b class="k">Rule</b>Coutume parallèle aux art. 2, par. 4, et 51 ; nécessité et proportionnalité.</div><div><b class="k">Application</b>Pas d’agression armée, pas de demande en temps utile, et des mesures ni nécessaires ni proportionnées.</div><div><b class="k">Conclusion</b>Les États-Unis ont violé le droit coutumier et devaient réparation.</div></div>`,
 sources:[{t:'CIJ : Nicaragua c. États-Unis',u:'https://www.icj-cij.org/case/70'}]},

{id:'c-lockerbie', title:'Quand le Conseil l’emporte sur un traité', where:'CIJ · Contentieux', when:'Lockerbie, ordonnances du 14 avril 1992 ; arrêts du 27 février 1998', tags:['Art. 103','Art. 25','Contrôle juridictionnel'],
 teaser:'La Libye invoque la Convention de Montréal pour garder deux suspects. Le Conseil de sécurité exige le contraire.',
 facts:`<p>Après l’attentat de 1988 contre le vol Pan Am 103, le Royaume-Uni et les États-Unis exigent la remise de deux suspects libyens. La Libye saisit la Cour sur le fondement de la Convention de Montréal de 1971. Trois jours après les audiences, le Conseil adopte la résolution 748 (1992) au titre du Chapitre VII. La Cour refuse d’indiquer des mesures conservatoires, car les obligations nées de la résolution prévalent en vertu de l’Article 103. En 1998, elle se déclare compétente et juge les requêtes recevables. Les affaires sont rayées du rôle en 2003.</p>`,
 decide:{q:'Vous représentez la Libye en 1992. Quelle est l’appréciation réaliste ?',o:[
  {t:'Les droits tirés de la Convention de Montréal prévaudront, car les traités priment les résolutions.',ok:false,why:'L’Article 103 donne la priorité aux obligations de la Charte, y compris les décisions obligatoires du Conseil.'},
  {t:'La Cour annulera à ce stade la résolution 748 comme ultra vires.',ok:false,why:'La Cour ne l’a pas annulée, et elle n’a pas de pouvoir général d’annulation.'},
  {t:'Des mesures conservatoires sont peu probables vu les Articles 25 et 103, mais le fond et la compétence restent à plaider.',ok:true,why:'C’est ce qui s’est produit : mesures refusées en 1992, compétence admise en 1998.'}]},
 questions:['La CIJ peut-elle contrôler les décisions du Conseil ?','Pourquoi la Cour s’est-elle encore déclarée compétente en 1998 malgré les résolutions 748 et 883 ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Des droits conventionnels pouvaient-ils faire obstacle, au moins à titre provisoire, aux exigences du Conseil ?</div><div><b class="k">Rule</b>Art. 25 et 103 ; Convention de Montréal, art. 7 et 14.</div><div><b class="k">Application</b>Prima facie, les obligations de la résolution prévalaient sur les droits conventionnels, qui ne se prêtaient donc pas à une protection.</div><div><b class="k">Conclusion</b>Mesures refusées ; compétence admise ultérieurement ; différend clos par désistement.</div></div>`,
 sources:[{t:'CIJ : Libye c. Royaume-Uni',u:'https://www.icj-cij.org/case/88'},{t:'CIJ : Libye c. États-Unis',u:'https://www.icj-cij.org/case/89'}]},

{id:'c-tadic', title:'Un tribunal examine le Conseil', where:'TPIY · Chambre d’appel', when:'Le Procureur c. Tadić, compétence, 2 octobre 1995', tags:['Art. 41','Ultra vires','Tribunaux'],
 teaser:'L’accusé soutient que le Conseil n’avait pas le pouvoir de créer une juridiction pénale. Le tribunal peut-il seulement se poser la question ?',
 facts:`<p>Duško Tadić conteste le TPIY, qu’il dit illégalement créé par la résolution 827 (1993) du Conseil. La Chambre d’appel juge qu’elle peut examiner sa propre compétence (compétence de la compétence), y compris la légalité de sa création. Elle estime que les pouvoirs du Conseil sont larges mais non illimités, et que la création d’un tribunal est une mesure relevant de l’Article 41. Elle juge aussi que des crimes de guerre peuvent être commis dans un conflit armé non international.</p>`,
 decide:{q:'Vous siégez à la Chambre d’appel. Que décidez-vous ?',o:[
  {t:'Examiner la contestation à titre incident, puis confirmer le tribunal comme mesure de l’Article 41.',ok:true,why:'La Chambre a jugé à la fois qu’elle pouvait examiner la question et que le tribunal était légal.'},
  {t:'Refuser : les décisions du Conseil sont politiques et ne peuvent jamais être examinées.',ok:false,why:'La Chambre a écarté la non-justiciabilité et souligné que le Conseil est lié par la Charte.'},
  {t:'Annuler la résolution, car l’Article 41 ne mentionne pas de tribunaux.',ok:false,why:'La liste de l’Article 41 est indicative ; un tribunal peut donc y entrer.'}]},
 questions:['En quoi le contrôle incident diffère-t-il d’un pouvoir d’annulation ?','Comment Tadić a-t-il changé le droit des conflits armés non internationaux ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Le TPIY a-t-il été légalement créé, et peut-il en décider ?</div><div><b class="k">Rule</b>Art. 39 et 41 ; compétence inhérente des organes judiciaires.</div><div><b class="k">Application</b>Le Conseil avait constaté une menace contre la paix, et les mesures n’impliquant pas l’emploi de la force peuvent inclure un organe judiciaire.</div><div><b class="k">Conclusion</b>La contestation a échoué ; le tribunal a été maintenu.</div></div>`,
 sources:[{t:'TPIY : décision de la Chambre d’appel',u:'https://www.icty.org/x/cases/tadic/acdec/en/51002.htm'},{t:'TPIY : page de l’affaire Tadić',u:'https://www.icty.org/en/case/tadic'}]},

{id:'c-mazilu', title:'Un rapporteur retenu chez lui', where:'CIJ · Avis consultatif', when:'Mazilu, 15 décembre 1989', tags:['Immunités','Convention de 1946','Experts en mission'],
 teaser:'Un expert roumain ne peut se rendre à Genève pour présenter son rapport. Son propre État dit que la Convention ne peut l’aider.',
 facts:`<p>Dumitru Mazilu, ressortissant roumain, est Rapporteur spécial de la Sous-Commission des droits de l’homme de l’ONU. La Roumanie ne le laisse pas voyager pour présenter son rapport et conteste l’application de la Convention. Par l’intermédiaire de l’ECOSOC, la question parvient à la Cour. Celle-ci juge qu’un rapporteur spécial est un expert en mission au sens de la section 22 de l’article VI de la Convention de 1946, et que ce statut s’applique même à l’égard de l’État de nationalité ou de résidence de l’expert.</p>`,
 decide:{q:'La Roumanie soutient que Mazilu est simplement son citoyen. Vous répondez :',o:[
  {t:'Les nationaux d’un État ne jouissent jamais des immunités de l’ONU à son égard.',ok:false,why:'La Cour a jugé que la section 22 s’applique aussi dans les relations de l’expert avec son propre État, sauf réserve valable.'},
  {t:'Il a le statut d’expert dès son mandat, y compris en Roumanie, même lorsqu’il ne voyage pas.',ok:true,why:'La Cour a jugé la section 22 applicable pendant tout le mandat, en déplacement ou non.'},
  {t:'Seul le personnel permanent est couvert, non les rapporteurs.',ok:false,why:'La section 22 vise les experts en mission qui ne sont pas fonctionnaires, et un rapporteur en est un.'}]},
 questions:['Pourquoi la protection doit-elle jouer contre l’État de nationalité ?','Un État pourrait-il formuler une réserve à cette règle ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>La section 22 de l’article VI s’applique-t-elle à Mazilu en Roumanie ?</div><div><b class="k">Rule</b>Convention de 1946, art. VI ; Charte, art. 105.</div><div><b class="k">Application</b>Il détenait un mandat de l’ONU confié par un organe de l’ONU ; la protection fonctionnelle doit le suivre.</div><div><b class="k">Conclusion</b>La section s’appliquait, et il avait droit aux facilités nécessaires à sa mission.</div></div>`,
 sources:[{t:'CIJ : Mazilu',u:'https://www.icj-cij.org/case/81'}]},

{id:'c-cumaraswamy', title:'Le rapporteur poursuivi pour une interview', where:'CIJ · Avis consultatif', when:'Cumaraswamy, 29 avril 1999', tags:['Immunités','Secrétaire général','Juridictions nationales'],
 teaser:'Des sociétés malaisiennes poursuivent un Rapporteur spécial pour une interview. Le Secrétaire général certifie qu’il agissait à titre officiel.',
 facts:`<p>Dato’ Param Cumaraswamy, Rapporteur spécial sur l’indépendance des juges et des avocats, est poursuivi en Malaisie pour diffamation à la suite d’une interview à un magazine. Le Secrétaire général conclut qu’il s’est exprimé à titre officiel et fait valoir l’immunité. Les tribunaux malaisiens poursuivent néanmoins. La Cour juge que la conclusion du Secrétaire général crée une présomption à laquelle les juridictions nationales doivent accorder le plus grand poids, que la question doit être traitée à titre préliminaire et que la Malaisie devait en informer ses tribunaux.</p>`,
 decide:{q:'Vous êtes le juge national. La note du Secrétaire général est sur votre bureau. Que faites-vous ?',o:[
  {t:'L’ignorer : seul le tribunal décide de l’immunité, et seulement après le procès.',ok:false,why:'La Cour a dit que l’immunité est une question préliminaire, à trancher rapidement.'},
  {t:'La traiter comme une présomption que seuls les motifs les plus impérieux peuvent renverser, et statuer d’abord sur l’immunité.',ok:true,why:'Cela suit le raisonnement de l’avis sur le rôle du Secrétaire général.'},
  {t:'La traiter comme concluante pour tous les actes de l’expert, y compris sa conduite privée.',ok:false,why:'L’immunité couvre les paroles et les actes accomplis au cours de la mission, non toute conduite.'}]},
 questions:['Qui supporte les frais lorsque la procédure nationale ignore l’immunité ?','Comment un rapporteur peut-il gérer ses contacts avec les médias en toute sécurité ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>La section 22, alinéa b), de l’article VI le protège-t-elle, et que doit faire la Malaisie ?</div><div><b class="k">Rule</b>Convention de 1946 ; Charte, art. 105 ; attribution à l’État du comportement de ses tribunaux.</div><div><b class="k">Application</b>La conclusion du Secrétaire général n’a pas été écartée, et les tribunaux n’ont pas traité l’immunité comme une question préalable.</div><div><b class="k">Conclusion</b>Il était couvert par l’immunité ; la Malaisie devait communiquer l’avis, et il ne devait supporter aucuns frais.</div></div>`,
 sources:[{t:'CIJ : Cumaraswamy',u:'https://www.icj-cij.org/case/100'}]},

{id:'c-behrami', title:'À qui imputer l’acte au Kosovo ?', where:'CEDH · Grande Chambre', when:'Behrami et Saramati, décision du 2 mai 2007', tags:['Attribution','Opérations de paix','Droits de l’homme'],
 teaser:'Un enfant est tué par une bombe non explosée et un homme est détenu par la KFOR. Les États contributeurs peuvent-ils répondre à Strasbourg ?',
 facts:`<p>En mars 2000, des enfants trouvent à Mitrovica des armes à sous-munitions non explosées ; Gadaf Behrami meurt et son frère Bekim est grièvement blessé. Ruzhdi Saramati est détenu en 2001 sur ordre du commandant de la KFOR. Les requérants se plaignent contre des États contributeurs au titre de la Convention européenne. La Grande Chambre conclut que le Conseil de sécurité a conservé l’autorité et le contrôle ultimes en vertu de la résolution 1244 (1999), que la supervision du déminage relevait de la MINUK et la détention de la KFOR, et que les actes sont imputables à l’ONU. Les requêtes sont irrecevables.</p>`,
 decide:{q:'Vous conseillez un État contributeur visé par cette requête. Quel est l’argument le plus solide au regard de la résolution 1244 ?',o:[
  {t:'La Convention ne s’applique jamais aux soldats servant à l’étranger.',ok:false,why:'La décision ne repose pas sur une telle règle ; elle porte sur l’attribution.'},
  {t:'Tout acte accompli dans une opération autorisée par l’ONU appartient automatiquement à l’État contributeur.',ok:false,why:'La Cour a abouti ici au résultat inverse, en imputant les actes à l’ONU.'},
  {t:'Le comportement est imputable à l’ONU, car le Conseil a conservé l’autorité et le contrôle ultimes ; la Cour n’est donc pas compétente.',ok:true,why:'C’est le raisonnement qui a rendu les requêtes irrecevables ratione personae.'}]},
 questions:['Pourquoi reproche-t-on à l’« autorité et contrôle ultimes » de différer du « contrôle effectif » ?','Vers qui ces requérants pouvaient-ils se tourner après l’échec de leur requête ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Les actes de la KFOR et de la MINUK sont-ils imputables aux États défendeurs ?</div><div><b class="k">Rule</b>Délégation au titre du Chapitre VII ; attribution d’un comportement aux organisations internationales ; CEDH, art. 1.</div><div><b class="k">Application</b>Le Conseil n’avait délégué que le commandement opérationnel et gardé l’autorité ultime ; les deux présences exerçaient des pouvoirs délégués par lui.</div><div><b class="k">Conclusion</b>Les actes étaient imputables à l’ONU et les requêtes irrecevables.</div></div>`,
 sources:[{t:'CEDH HUDOC : Behrami et Saramati',u:'https://hudoc.echr.coe.int/eng?i=001-80830'}]},

{id:'c-aljedda', title:'Une détention britannique sous mandat de l’ONU', where:'CEDH · Grande Chambre', when:'Al-Jedda c. Royaume-Uni, 7 juillet 2011', tags:['Attribution','Art. 103','Détention'],
 teaser:'Un homme est interné plus de trois ans à Bassora sans inculpation. Le Royaume-Uni dit que l’ONU est responsable et que le Conseil l’exigeait.',
 facts:`<p>Hilal Al-Jedda est interné par les forces britanniques en Irak de 2004 à 2007 pour des raisons de sécurité, sans inculpation. Le Royaume-Uni soutient que la détention est imputable à l’ONU et que la résolution 1546 (2004) écarte l’article 5 de la CEDH par l’effet de l’Article 103 de la Charte. La Grande Chambre juge que le Conseil n’exerçait ni contrôle effectif ni autorité et contrôle ultimes sur la Force multinationale, et que le comportement est donc imputable au Royaume-Uni. Elle juge aussi que la résolution n’exigeait pas clairement l’internement et constate une violation de l’article 5, paragraphe 1.</p>`,
 decide:{q:'Vous êtes conseil du Royaume-Uni. Comment évaluez-vous l’affaire après Behrami ?',o:[
  {t:'L’imputation au Royaume-Uni est probable, car le Conseil a autorisé la force sans la commander ; et l’Article 103 n’aide que si la résolution exige clairement la détention.',ok:true,why:'Ces deux volets reflètent l’arrêt, y compris sa présomption selon laquelle le Conseil n’entend pas violer les droits de l’homme.'},
  {t:'Behrami règle tout : toute opération autorisée par l’ONU est un comportement de l’ONU.',ok:false,why:'La Cour a distingué le Kosovo de l’Irak.'},
  {t:'L’Article 103 supprime toute obligation en matière de droits de l’homme dès qu’existe une résolution du Chapitre VII.',ok:false,why:'La Cour a interprété la résolution de manière à éviter le conflit et n’y a vu aucune obligation d’interner.'}]},
 questions:['Quel libellé aurait été nécessaire pour écarter l’article 5 ?','Que doit retenir de cette affaire une procédure opérationnelle de détention en mission ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>L’internement est-il imputable au Royaume-Uni, et la résolution 1546 écartait-elle l’article 5 ?</div><div><b class="k">Rule</b>CEDH, art. 1 et 5 ; Charte, art. 25 et 103 ; présomption d’absence de conflit avec les droits de l’homme.</div><div><b class="k">Application</b>La Force n’était pas sous commandement de l’ONU, et la résolution autorisait l’internement sans l’exiger en termes clairs.</div><div><b class="k">Conclusion</b>Le comportement était imputable au Royaume-Uni, qui a violé l’article 5, paragraphe 1.</div></div>`,
 trainer:'<p>Rapprochez cette affaire de Behrami et demandez : opération autorisée ou opération commandée par l’ONU ? Cette question détermine le résultat.</p>',
 sources:[{t:'CEDH HUDOC : Al-Jedda',u:'https://hudoc.echr.coe.int/eng?i=001-105612'},{t:'EJIL:Talk! : Al-Skeini et Al-Jedda',u:'https://www.ejiltalk.org/european-court-decides-al-skeini-and-al-jedda/'}]},

{id:'c-kadi', title:'Inscription sur une liste de sanctions et droit d’être entendu', where:'Cour de justice de l’Union européenne', when:'Kadi I, 3 septembre 2008 ; Kadi II, 18 juillet 2013', tags:['Sanctions','Art. 103','Garanties procédurales'],
 teaser:'Un homme voit ses avoirs gelés à cause d’une liste de l’ONU dont il ignore les motifs. Une juridiction régionale peut-elle contrôler la mesure ?',
 facts:`<p>Yassin Abdullah Kadi est inscrit en 2001 par le Comité des sanctions 1267, et l’UE gèle ses avoirs par règlement. Le Tribunal de première instance ne contrôle la mesure qu’au regard du jus cogens. En 2008, la Cour de justice annule cette approche : elle contrôle l’acte de l’UE, et non la résolution elle-même, au regard des droits fondamentaux, et l’annule pour violation des droits de la défense et de la protection juridictionnelle effective. Le Bureau du Médiateur est créé par la résolution 1904 (2009). Dans Kadi II, la Cour confirme l’annulation de la nouvelle inscription ; l’ONU l’avait radié en 2012.</p>`,
 decide:{q:'Vous êtes juge de l’UE en 2008. Que décidez-vous ?',o:[
  {t:'Annuler la résolution de l’ONU, car elle viole les droits fondamentaux.',ok:false,why:'La Cour n’a expressément pas contrôlé la résolution ; elle a contrôlé l’acte de mise en œuvre de l’UE.'},
  {t:'Refuser tout contrôle : l’Article 103 met l’acte de mise en œuvre hors de portée de toute juridiction.',ok:false,why:'La Cour a refusé toute immunité de contrôle à la mesure de l’UE.'},
  {t:'Contrôler l’acte de mise en œuvre de l’UE au regard des droits fondamentaux, sans statuer sur la résolution elle-même.',ok:true,why:'C’est le cœur de l’arrêt de 2008.'}]},
 questions:['Kadi respecte-t-il ou affaiblit-il l’Article 103 ?','Le Médiateur satisfait-il aux garanties procédurales, et pourquoi ne couvre-t-il que le régime EIIL et Al-Qaida ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Les juridictions de l’UE peuvent-elles contrôler une mesure mettant en œuvre une inscription au titre du Chapitre VII ?</div><div><b class="k">Rule</b>Charte, art. 25 et 103 ; droits fondamentaux de l’UE ; droits de la défense.</div><div><b class="k">Application</b>La Charte n’impose pas la manière de mettre en œuvre les obligations en droit interne. Kadi n’a jamais connu les motifs ni été entendu.</div><div><b class="k">Conclusion</b>Le règlement a été annulé en ce qui le concerne ; en 2013, la Cour a confirmé que les motifs doivent être communiqués et suffisamment étayés.</div></div>`,
 sources:[{t:'CJUE : affaires jointes C-402/05 P et C-415/05 P',u:'https://curia.europa.eu/juris/liste.jsf?num=C-402/05'},{t:'CJUE : affaires jointes C-584/10 P et autres',u:'https://curia.europa.eu/juris/liste.jsf?num=C-584/10'},{t:'ONU : Bureau du Médiateur',u:'https://main.un.org/securitycouncil/en/ombudsperson'}]},

{id:'c-nuhanovic', title:'Dutchbat et la famille de l’interprète', where:'Pays-Bas · Cour suprême', when:'Pays-Bas c. Nuhanović, 6 septembre 2013', tags:['Attribution','Double attribution','Srebrenica'],
 teaser:'La famille d’un interprète de l’ONU est renvoyée hors du camp à Srebrenica. L’État contributeur peut-il être responsable ?',
 facts:`<p>Hasan Nuhanović est interprète pour le bataillon néerlandais de la FORPRONU. Après la chute de Srebrenica en juillet 1995, son père, sa mère et son frère doivent quitter le camp, et ils sont tués. Une demande parallèle concerne l’électricien Rizo Mustafić. La Cour suprême confirme la Cour d’appel de La Haye : l’attribution dépend du contrôle effectif sur le comportement précis, un comportement peut être attribué à la fois à l’ONU et à un État, et les Pays-Bas exerçaient un tel contrôle pendant l’évacuation. L’État est responsable.</p>`,
 decide:{q:'L’État soutient que Dutchbat portait le casque bleu, donc que seule l’ONU peut répondre. Vous répondez :',o:[
  {t:'Le transfert à l’ONU ne clôt pas la question : le contrôle effectif sur l’acte précis décide, et l’État peut lui aussi le détenir.',ok:true,why:'C’est le raisonnement confirmé par la Cour suprême.'},
  {t:'Les contingents nationaux ne répondent jamais qu’à leur propre État.',ok:false,why:'Normalement, le comportement d’un contingent mis à la disposition de l’ONU est attribué à l’ONU ; ici, les faits en ont décidé autrement.'},
  {t:'Seule l’ONU, qui est immune, peut être responsable : la demande doit donc échouer.',ok:false,why:'La Cour a écarté l’attribution exclusive.'}]},
 questions:['Quels faits ont montré le contrôle néerlandais pendant l’évacuation ?','Comment un commandant de contingent doit-il traiter des ordres venant de sa capitale ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Le comportement de Dutchbat est-il attribuable aux Pays-Bas ?</div><div><b class="k">Rule</b>Contrôle effectif, à la lumière des articles de la CDI sur la responsabilité des États et des organisations ; double attribution.</div><div><b class="k">Application</b>Dans la transition suivant la chute, le Gouvernement néerlandais était étroitement associé à l’évacuation et aurait pu empêcher le comportement.</div><div><b class="k">Conclusion</b>Le comportement était attribuable aux Pays-Bas, qui ont agi de façon illicite.</div></div>`,
 sources:[{t:'Cour suprême néerlandaise : ECLI:NL:HR:2013:BZ9225',u:'https://uitspraken.rechtspraak.nl/details?id=ECLI:NL:HR:2013:BZ9225'},{t:'Prakken d’Oliveira : arrêt de la Cour suprême',u:'https://www.prakkendoliveira.nl/en/news/2013/supreme-court-dutch-state-is-responsible-for-death-of-three-muslim-men-in-srebrenica'}]},

{id:'c-mothers', title:'Poursuivre l’ONU pour Srebrenica', where:'Pays-Bas · Cour suprême ; CEDH', when:'Cour suprême 13 avril 2012 ; CEDH 11 juin 2013 ; Cour suprême 19 juillet 2019', tags:['Immunités','Accès à un tribunal','Srebrenica'],
 teaser:'Des milliers de proches poursuivent l’ONU et les Pays-Bas. Le génocide est-il une exception à l’immunité de l’ONU ?',
 facts:`<p>La fondation Mères de Srebrenica et des proches poursuivent l’ONU et les Pays-Bas devant les tribunaux néerlandais. En 2012, la Cour suprême confirme l’immunité absolue de l’ONU, malgré la gravité des allégations. En 2013, Strasbourg déclare le grief irrecevable : l’immunité prévue par la Charte et la Convention de 1946 poursuit un but légitime, et l’absence d’autre recours ne viole pas en soi l’accès à un tribunal. L’action contre l’État se poursuit. En 2019, la Cour suprême tient les Pays-Bas responsables du comportement de Dutchbat envers environ 350 hommes présents dans le camp, mais à hauteur de 10 % seulement du dommage, soit la chance perdue de survie.</p>`,
 decide:{q:'Vous êtes le juge néerlandais en 2012. Que faites-vous de la demande contre l’ONU ?',o:[
  {t:'Écarter l’immunité : des allégations de génocide l’emportent sur toute immunité.',ok:false,why:'Les juridictions ont jugé que la gravité des allégations n’écarte pas l’immunité de l’ONU.'},
  {t:'Confirmer l’immunité de l’ONU, tout en laissant se poursuivre la demande distincte contre l’État.',ok:true,why:'C’est ainsi que la procédure s’est effectivement scindée.'},
  {t:'Renvoyer la demande à la CIJ, qui connaît des réclamations individuelles.',ok:false,why:'Seuls les États peuvent être parties devant la CIJ au contentieux (Statut, art. 34).'}]},
 questions:['Qu’exige la section 29 de la Convention de 1946, et que se passe-t-il si elle n’est pas respectée ?','Pourquoi la responsabilité est-elle tombée à 10 % ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>L’ONU peut-elle être poursuivie devant les juridictions nationales pour Srebrenica, et l’État est-il responsable ?</div><div><b class="k">Rule</b>Charte, art. 105 ; Convention de 1946, art. II, s. 2 et s. 29 ; CEDH, art. 6 ; contrôle effectif.</div><div><b class="k">Application</b>L’immunité sert le fonctionnement de l’ONU et ne connaît pas d’exception liée à la gravité. La responsabilité de l’État repose sur le comportement de Dutchbat pendant l’évacuation.</div><div><b class="k">Conclusion</b>L’ONU était immune ; l’État a supporté une responsabilité limitée à 10 %.</div></div>`,
 sources:[{t:'Cour suprême néerlandaise : ECLI:NL:HR:2019:1223',u:'https://uitspraken.rechtspraak.nl/details?id=ECLI:NL:HR:2019:1223'},{t:'EJIL:Talk! : fin du contentieux',u:'https://www.ejiltalk.org/a-disappointing-end-of-the-road-for-the-mothers-of-srebrenica-litigation-in-the-netherlands/'}]},

{id:'c-georges', title:'Le choléra en Haïti et un prétoire fermé', where:'États-Unis · Cour d’appel du deuxième circuit', when:'Georges c. Nations Unies, 18 août 2016', tags:['Immunités','Section 29','Choléra en Haïti'],
 teaser:'Le choléra apparaît près d’un camp de Casques bleus. L’ONU refuse d’ouvrir une procédure de réclamation. Perd-elle pour autant son immunité ?',
 facts:`<p>Le choléra atteint Haïti en octobre 2010, des éléments le reliant à un camp de la MINUSTAH, et des milliers de personnes meurent. En 2013, l’ONU juge irrecevables les réclamations des victimes, qui agissent à New York. Elles soutiennent que l’absence de mode de règlement prévu à la section 29 de la Convention de 1946 fait perdre à l’ONU l’immunité de la section 2. Le deuxième circuit rejette cette thèse : cette obligation n’est pas une condition préalable de l’immunité. En décembre 2016, le Secrétaire général présente ses excuses et une nouvelle stratégie à l’Assemblée (A/71/620).</p>`,
 decide:{q:'Vous êtes conseiller juridique de l’ONU après le jugement. Quelle affirmation guide le mieux votre avis ?',o:[
  {t:'L’immunité a tenu devant le juge, mais l’obligation de la section 29 demeure : gagner ne règle pas la question de la responsabilité.',ok:true,why:'La cour ne s’est prononcée que sur l’immunité, et l’ONU a ensuite reconnu une responsabilité morale et adopté une nouvelle stratégie.'},
  {t:'Le jugement prouve que l’ONU ne doit rien à personne en Haïti.',ok:false,why:'Il a seulement décidé que l’ONU était à l’abri de poursuites, non qu’elle n’avait aucune obligation.'},
  {t:'L’ONU doit s’attendre à perdre devant tout autre tribunal américain, la section 29 conditionnant l’immunité.',ok:false,why:'Le deuxième circuit a expressément jugé le contraire.'}]},
 questions:['Quelle différence ici entre responsabilité juridique et responsabilité morale ?','Comment les missions doivent-elles planifier la gestion des déchets, et qui paierait en cas d’erreur ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>La section 29 est-elle une condition préalable de l’immunité prévue à la section 2 ?</div><div><b class="k">Rule</b>Convention de 1946, s. 2 et 29 ; Charte, art. 105.</div><div><b class="k">Application</b>La section 2 accorde l’immunité en termes absolus, sauf renonciation expresse ; rien dans le texte ne la lie à la section 29.</div><div><b class="k">Conclusion</b>Le rejet a été confirmé. La question de la réparation s’est déplacée sur le plan politique.</div></div>`,
 sources:[{t:'Décision du deuxième circuit (copie IJDH)',u:'https://www.ijdh.org/wp-content/uploads/2011/11/2d-Circuit-Decision.pdf'},{t:'ONU : SG/SM/17991',u:'https://press.un.org/en/2016/sgsm17991.doc.htm'},{t:'A/71/620',u:'https://undocs.org/A/71/620'}]},

{id:'c-rwanda', title:'Le télégramme de janvier depuis Kigali', where:'ONU · Enquête indépendante', when:'Rapport du 15 décembre 1999 (S/1999/1257), sur le génocide de 1994', tags:['Enquête','MINUAR','Prévention'],
 teaser:'Un commandant de la force signale des caches d’armes et un plan de massacres. Le Siège lui demande de s’en tenir au mandat.',
 facts:`<p>Le 11 janvier 1994, le général de division Roméo Dallaire, de la MINUAR, adresse à New York un télégramme sur les avertissements d’un informateur concernant des caches d’armes et des plans de massacres, et propose de saisir les armes. Le Siège lui demande de ne pas agir, mais d’informer le Président et certaines ambassades. Après le début des massacres en avril 1994, le Conseil réduit fortement la MINUAR par la résolution 912 (1994). L’Enquête indépendante présidée par Ingvar Carlsson constate un échec global, marqué par le manque de ressources et de volonté politique, et relève des erreurs dans le traitement du télégramme et du mandat.</p>`,
 decide:{q:'Vous êtes chargé du dossier à New York lorsque le télégramme arrive. Quelle est la meilleure conduite ?',o:[
  {t:'Répondre que le mandat n’autorise pas de raid, et classer l’affaire.',ok:false,why:'L’Enquête a critiqué le fait de ne pas avoir pris l’alerte assez au sérieux ni porté pleinement au Conseil.'},
  {t:'Dire au commandant de la force de lancer le raid aussitôt, de sa propre autorité et sans informer personne.',ok:false,why:'Une opération hors mandat sur un renseignement incertain, avec des forces faibles, comporte de graves risques et contourne la décision politique.'},
  {t:'Transmettre intégralement l’alerte aux hauts responsables et au Conseil, et élaborer des options, tandis que la mission se protège et vérifie.',ok:true,why:'La leçon centrale de l’Enquête est que l’alerte rapide doit atteindre les décideurs et produire une véritable réponse.'}]},
 questions:['Qu’auriez-vous demandé au Conseil de modifier dans le mandat ?','Comment cette enquête influence-t-elle aujourd’hui la doctrine de protection des civils ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Comment l’ONU doit-elle répondre à une alerte d’atrocités de masse dans le cadre d’un mandat limité ?</div><div><b class="k">Rule</b>Mandat (résolution 872 (1993)) ; Charte, art. 99 ; obligation de prévention de la Convention sur le génocide.</div><div><b class="k">Application</b>Un mandat de Chapitre VI et de maigres ressources limitaient l’action, mais ces limites appelaient une remontée de l’alerte, non le silence.</div><div><b class="k">Conclusion</b>L’Enquête a constaté un échec de l’institution et des États Membres et recommandé des plans d’action pour prévenir le génocide.</div></div>`,
 sources:[{t:'Bibliothèque numérique de l’ONU : S/1999/1257',u:'https://digitallibrary.un.org/record/405039'},{t:'Communiqué de l’ONU sur l’Enquête',u:'https://press.un.org/en/1999/19991216.rwanda.doc.html'}]},

{id:'c-srebrenica', title:'Une zone de sécurité qui ne l’était pas', where:'ONU · Rapport du Secrétaire général', when:'La chute de Srebrenica, A/54/549, 15 novembre 1999', tags:['Enquête','Zones de sécurité','Emploi de la force'],
 teaser:'Une zone de sécurité déclarée par l’ONU tombe en quelques jours, et plus de 7 000 hommes et garçons sont tués. L’ONU enquête sur elle-même.',
 facts:`<p>Les résolutions 819 et 824 (1993) du Conseil de sécurité déclarent Srebrenica et d’autres villes zones de sécurité, avec une FORPRONU légèrement armée et sans moyens de les défendre. Les forces serbes de Bosnie prennent la ville le 11 juillet 1995, puis tuent plus de 7 000 hommes et garçons bosniaques. Le rapport du Secrétaire général, demandé par l’Assemblée, reconnaît des erreurs de jugement de l’ONU, notamment un état d’esprit d’impartialité face à une tentative de nettoyage ethnique, et des défaillances dans l’emploi de la puissance aérienne. Il affirme qu’une telle tentative doit être combattue avec détermination.</p>`,
 decide:{q:'Vous rédigez pour le Conseil le mandat sur les zones de sécurité en 1993. Sur quoi insistez-vous ?',o:[
  {t:'Des définitions claires, des conditions de démilitarisation, des forces et des moyens à la hauteur de la tâche, ou sinon un avertissement franc que la promesse ne peut être tenue.',ok:true,why:'La leçon du rapport est qu’on ne doit pas promettre une protection sans les moyens et la volonté de l’assurer.'},
  {t:'Garder un libellé vague, pour ne pas inquiéter les pays contributeurs de troupes.',ok:false,why:'Les mandats ambigus sont une défaillance centrale relevée par le rapport.'},
  {t:'S’en remettre au seul drapeau de l’ONU, car aucune partie n’attaquera des Casques bleus.',ok:false,why:'Les événements de Srebrenica l’ont démenti.'}]},
 questions:['L’impartialité équivaut-elle à la neutralité ?','Quel lien entre ce rapport et le rapport Brahimi de 2000 ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Qu’est-ce qui a échoué, et qu’exige la promesse d’une zone de sécurité ?</div><div><b class="k">Rule</b>Résolutions 819, 824, 836 (1993) ; Chapitre VII ; obligations attachées au mandat.</div><div><b class="k">Application</b>Trop peu de troupes, pas de démilitarisation convenue, réticence à employer la puissance aérienne, neutralité face au nettoyage ethnique.</div><div><b class="k">Conclusion</b>L’ONU a sa part dans l’échec. La protection exige des mandats clairs, des moyens suffisants et la volonté d’employer la force.</div></div>`,
 trainer:'<p>Associez ce cas à c-nuhanovic et c-mothers : un même événement, trois niveaux de responsabilité.</p>',
 sources:[{t:'A/54/549',u:'https://undocs.org/A/54/549'}]},

{id:'c-fib', title:'Des Casques bleus avec un mandat offensif', where:'ONU · Conseil de sécurité', when:'Résolution 2098, 28 mars 2013 (MONUSCO)', tags:['Emploi de la force','Mandats','DIH'],
 teaser:'Le Conseil crée au sein d’une mission de maintien de la paix une brigade chargée de « neutraliser » des groupes armés. Ses membres restent-ils protégés ?',
 facts:`<p>Après la prise de Goma par le M23 en novembre 2012, le Conseil adopte à l’unanimité la résolution 2098 (2013). Elle crée au sein de la MONUSCO une brigade d’intervention de trois bataillons d’infanterie avec des unités d’appui, sous l’autorité du commandant de la force, pour mener des opérations offensives ciblées visant à neutraliser et désarmer les groupes armés. Le Conseil précise que cette mesure est exceptionnelle et ne crée pas de précédent quant aux principes convenus du maintien de la paix. La brigade contribue à la défaite du M23 plus tard en 2013. Vérifiez le statut actuel de la brigade et de la MONUSCO avant d’enseigner ce cas.</p>`,
 decide:{q:'Un contingent vous demande : le mandat de la brigade change-t-il notre situation juridique ?',o:[
  {t:'Non : la formule « sans précédent » du Conseil signifie que le DIH ne peut jamais s’appliquer aux forces de l’ONU.',ok:false,why:'L’applicabilité du DIH dépend des faits sur le terrain ; le libellé d’une résolution ne l’écarte pas.'},
  {t:'Oui : lors des hostilités, ses membres peuvent être des combattants au regard du DIH, et le risque s’étend à la protection de la Convention de 1994 sur la sécurité.',ok:true,why:'Cela reflète la circulaire ST/SGB/1999/13 et l’article 2, paragraphe 2, de la Convention de 1994, et c’est le cœur du débat juridique.'},
  {t:'Oui : le mandat permet à la brigade d’agir hors de la chaîne de commandement de la mission.',ok:false,why:'La brigade relève du commandant de la force de la MONUSCO.'}]},
 questions:['La mission entière pourrait-elle être considérée comme partie au conflit ?','Qu’est-ce que cela implique pour les humanitaires travaillant près de la brigade ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Quelles conséquences juridiques découlent d’un mandat offensif au sein d’une mission de maintien de la paix ?</div><div><b class="k">Rule</b>Résolution 2098 ; ST/SGB/1999/13 ; Convention de 1994, art. 2, par. 2 ; seuil du DIH.</div><div><b class="k">Application</b>Des opérations offensives ciblées contre des groupes organisés peuvent atteindre le seuil de la participation aux hostilités.</div><div><b class="k">Conclusion</b>Le mandat est valide, mais les commandants doivent planifier comme si le DIH s’appliquait et expliquer les risques aux contingents.</div></div>`,
 sources:[{t:'ONU : SC/10964',u:'https://press.un.org/en/2013/sc10964.doc.htm'},{t:'S/RES/2098 (2013)',u:'https://undocs.org/S/RES/2098(2013)'},{t:'ASIL : questions juridiques',u:'https://asil.org/insights/volume-17-issue-15/'}]},

{id:'c-juba', title:'Terrain : l’appel resté sans réponse', where:'ONU · Enquête spéciale indépendante', when:'Rapport Cammaert, résumé publié le 1er novembre 2016', tags:['Protection des civils','Commandement','Enquête'],
 teaser:'Des soldats gouvernementaux attaquent un camp près d’une base de l’ONU à Djouba. Des appels à l’aide sont lancés, et aucune force n’arrive.',
 facts:`<p>Des combats éclatent à Djouba en juillet 2016. Le 11 juillet, des soldats attaquent le camp de Terrain, un site privé hébergeant des travailleurs humanitaires ; des personnes sont battues, volées et violées, et un journaliste local est tué. Le Secrétaire général Ban Ki-moon nomme le 23 août le général de division (à la retraite) Patrick Cammaert pour enquêter. Le résumé conclut qu’un manque de leadership, de préparation et d’intégration entre les composantes de la mission a contribué à l’absence de réaction à Terrain et de protection des civils. Le Secrétaire général demande le remplacement du commandant de la force.</p>`,
 decide:{q:'Vous êtes officier de permanence lorsque l’appel de Terrain arrive. Que le système aurait-il dû produire ?',o:[
  {t:'Aucune action : Terrain est une propriété privée hors de la base de l’ONU.',ok:false,why:'La protection des civils sous menace imminente, dans la limite des capacités, ne se réduit pas aux locaux de l’ONU.'},
  {t:'Un ordre clair d’un seul commandant d’envoyer une force capable, avec une décision consignée, et les motifs signalés si elle ne peut partir.',ok:true,why:'Les critiques de l’enquête portent sur le leadership, l’intégration et l’absence de réaction.'},
  {t:'Chaque contingent devrait consulter sa capitale et agir si elle est d’accord.',ok:false,why:'Des instructions nationales parallèles sapent l’unité de commandement dont la mission avait besoin.'}]},
 questions:['Que signifie « dans la limite de ses capacités », et qui en décide ?','Que faut-il répéter avant une crise ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>La MINUSS a-t-elle rempli son mandat de protection et ses responsabilités de commandement ?</div><div><b class="k">Rule</b>Mandat de la MINUSS (protection des civils au titre du Chapitre VII) ; directive sur l’emploi de la force et règles d’engagement ; unité de commandement.</div><div><b class="k">Application</b>Les alertes et les appels n’ont pas produit de réponse coordonnée, et les composantes de la mission n’étaient pas intégrées.</div><div><b class="k">Conclusion</b>La réponse a été insuffisante. Les leçons sont le leadership, des plans répétés et la responsabilité.</div></div>`,
 trainer:'<p>Jouez ce cas comme un exercice de poste de commandement chronométré, l’appel arrivant alors que la base elle-même est sous le feu.</p>',
 sources:[{t:'Résumé analytique (copie)',u:'https://walterdorn.org/pdf/Cammaert-Report-UNMISS_Public_Executive_Summary_on_the_Special_Investigation_Report_1_Nov_2016.pdf'},{t:'Déclaration du porte-parole, 1er novembre 2016',u:'https://unmiss.unmissions.org/sites/default/files/statement_attributable_to_the_spokesman_for_the_secretary_01_11_2016.pdf'}]},

{id:'c-opt', title:'Une occupation jugée illicite', where:'CIJ · Avis consultatif', when:'Territoire palestinien occupé, 19 juillet 2024', tags:['Occupation','Autodétermination','Obligations des États et de l’ONU'],
 teaser:'L’Assemblée s’interroge sur les conséquences juridiques des politiques d’Israël. La réponse concerne les États tiers et l’ONU elle-même.',
 facts:`<p>Par la résolution 77/247, l’Assemblée générale demande un avis sur les politiques et pratiques d’Israël dans le Territoire palestinien occupé. La Cour conclut que la présence continue d’Israël y est illicite (11 voix contre 4) et doit cesser dans les plus brefs délais, que toute nouvelle activité de colonisation doit cesser et les colons être évacués, et qu’une réparation est due (14 contre 1 sur chaque point). Par 12 voix contre 3, elle dit que tous les États doivent ne pas reconnaître la situation comme licite ni aider à son maintien, et que les organisations internationales, dont l’ONU, doivent aussi ne pas la reconnaître. Israël a rejeté l’avis.</p>`,
 decide:{q:'Un délégué vous demande ce que cet avis signifie pour le travail de l’ONU. Vous répondez :',o:[
  {t:'Rien : les avis consultatifs n’ont d’effet sur personne.',ok:false,why:'Ils ne sont pas obligatoires en tant que tels, mais ils énoncent le droit avec autorité, et celui-ci vise expressément l’ONU.'},
  {t:'Il est obligatoire comme un arrêt au titre de l’Article 94.',ok:false,why:'L’Article 94 concerne les arrêts rendus au contentieux.'},
  {t:'Il n’est pas obligatoire en tant que tel, mais il énonce des obligations existantes, et il dit que l’ONU ne doit pas reconnaître la situation et devrait envisager d’autres mesures pour y mettre fin.',ok:true,why:'Cela correspond au statut d’un avis consultatif et aux conclusions de la Cour concernant l’ONU.'}]},
 questions:['Comment les obligations de non-reconnaissance touchent-elles une mission ou une agence opérant sur le territoire ?','Comparez avec la Namibie (1971) : quelles similitudes ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Quelles sont les conséquences juridiques des politiques d’Israël et de sa présence continue ?</div><div><b class="k">Rule</b>Interdiction d’acquérir un territoire par la force ; autodétermination ; droit de l’occupation ; droit des droits de l’homme.</div><div><b class="k">Application</b>L’annexion et l’affirmation de souveraineté ont violé cette interdiction et entravé l’autodétermination, et les restrictions constituaient une discrimination systémique.</div><div><b class="k">Conclusion</b>La présence est illicite et doit cesser ; des obligations de non-reconnaissance et de non-assistance naissent pour les États, la non-reconnaissance s’appliquant aussi aux organisations.</div></div>`,
 sources:[{t:'CIJ : page de l’affaire',u:'https://www.icj-cij.org/case/186'},{t:'ONU : résumé de l’avis',u:'https://www.un.org/unispal/document/summary-of-the-icj-order-icj-19jul24/'}]},

{id:'c-climate', title:'Le changement climatique comme obligation juridique', where:'CIJ · Avis consultatif', when:'Obligations des États en matière de changement climatique, 23 juillet 2025', tags:['Climat','Responsabilité de l’État','Avis consultatifs'],
 teaser:'Des États insulaires portent une question à l’Assemblée, puis à la Cour. Les engagements climatiques ne sont-ils que politiques ?',
 facts:`<p>À la suite d’une campagne menée par Vanuatu, l’Assemblée demande un avis par la résolution 77/276 (2023). Dans un avis unanime, la Cour juge que les traités sur le climat, les obligations coutumières et d’autres règles s’appliquent tous, et non les seuls traités. Elle considère l’objectif de 1,5 °C comme le principal objectif convenu. Elle dit que le fait de ne pas prendre les mesures appropriées pour protéger le système climatique, y compris par la production, la consommation et l’octroi de permis pour les combustibles fossiles, peut constituer un fait internationalement illicite, avec des conséquences juridiques comprenant une possible réparation.</p>`,
 decide:{q:'Un ministre déclare : « Nous avons signé l’Accord de Paris, rien d’autre ne nous lie, et notre engagement ne regarde que nous. » Vous conseillez :',o:[
  {t:'Exact : seuls les traités sur le climat s’appliquent, en tant que loi spéciale.',ok:false,why:'La Cour a écarté l’idée que ces traités évincent les autres règles.'},
  {t:'Non : l’Accord de Paris s’applique avec la coutume et d’autres règles, et la latitude sur l’engagement est limitée par une obligation de diligence requise.',ok:true,why:'C’est un exposé fidèle de l’approche de la Cour.'},
  {t:'L’avis a ordonné à votre État de verser une indemnisation.',ok:false,why:'Un avis consultatif n’ordonne à aucun État de payer ; il énonce les conséquences juridiques en termes généraux.'}]},
 questions:['Comment l’avis peut-il être utilisé devant les juridictions nationales ou d’autres juridictions internationales ?','Pourquoi la causalité collective ne fait-elle pas obstacle à la responsabilité ?'],
 solution:`<div class="irac"><div><b class="k">Issue</b>Quelles sont les obligations des États en matière de climat, et que découle-t-il d’une violation ?</div><div><b class="k">Rule</b>CCNUCC, Protocole de Kyoto, Accord de Paris ; obligation coutumière de prévenir les dommages significatifs ; CNUDM ; droit des droits de l’homme.</div><div><b class="k">Application</b>La science, dont les conclusions du GIEC, établit un risque grave ; des obligations de diligence requise et de coopération s’appliquent donc aux activités émettrices.</div><div><b class="k">Conclusion</b>Les États ont des obligations contraignantes ; leur violation peut engager leur responsabilité, même si l’avis lui-même est consultatif.</div></div>`,
 sources:[{t:'CIJ : page de l’affaire',u:'https://www.icj-cij.org/case/187'},{t:'IISD ENB : compte rendu',u:'https://enb.iisd.org/international-court-justice-advisory-opinion-climate-change-briefing-note'}]},
];
